# Pulumi ComponentResource: Web Infra

## Project structure

```
web-infra/
├── Pulumi.yaml
├── package.json
├── tsconfig.json
├── index.ts
├── config.ts
├── components/
│   └── web-app-stack.ts
├── Pulumi.dev.yaml
└── Pulumi.prod.yaml
```

## Pulumi.yaml

```yaml
name: web-infra
runtime: nodejs
description: Stateless web app infrastructure (S3 + RDS + IAM)
```

## config.ts

```typescript
import * as pulumi from "@pulumi/pulumi";

export interface EnvConfig {
    environment: "dev" | "prod";
    region: string;
    bucketReplication: boolean;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
}

export function loadConfig(): EnvConfig {
    const cfg = new pulumi.Config();
    const environment = cfg.require("environment") as "dev" | "prod";

    if (environment !== "dev" && environment !== "prod") {
        throw new Error(`Invalid environment: ${environment}`);
    }

    const defaults: EnvConfig = environment === "prod"
        ? {
            environment,
            region: "us-east-1",
            bucketReplication: true,   // cross-region replication to us-west-2
            dbInstanceClass: "db.t3.medium",
            dbMultiAz: true,
            dbAllocatedStorage: 50,
        }
        : {
            environment,
            region: "us-east-1",
            bucketReplication: false,
            dbInstanceClass: "db.t3.micro",
            dbMultiAz: false,
            dbAllocatedStorage: 20,
        };

    return {
        ...defaults,
        region: cfg.get("region") ?? defaults.region,
        dbInstanceClass: cfg.get("dbInstanceClass") ?? defaults.dbInstanceClass,
    };
}
```

## components/web-app-stack.ts

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { EnvConfig } from "../config";

export interface WebAppStackArgs {
    env: EnvConfig;
    dbPassword: pulumi.Output<string>; // secret from ConfigSecret
}

export class WebAppStack extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly replicationRoleArn: pulumi.Output<string> | undefined;
    public readonly db: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;

    constructor(name: string, args: WebAppStackArgs, opts?: pulumi.ComponentResourceOptions) {
        super("webinfra:components:WebAppStack", name, args, opts);

        const { env } = args;
        const isProd = env.environment === "prod";

        // --- S3 bucket: versioned, encrypted, no public access ---
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {}, { parent: this });
        this.bucket = bucket;

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-encryption`, {
            bucket: bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                bucketKeyEnabled: true,
            }],
        }, { parent: this });

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // --- Cross-region replication (prod only) ---
        if (env.bucketReplication && isProd) {
            const replBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {}, { parent: this });
            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this });

            const replRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                    Service: "s3.amazonaws.com",
                }),
                // Least privilege: only replication actions on this bucket
                inlinePolicies: [{
                    name: "replication",
                    policy: pulumi.all([bucket.arn, replBucket.arn]).apply(([src, dst]) =>
                        JSON.stringify({
                            Version: "2012-10-17",
                            Statement: [{
                                Effect: "Allow",
                                Action: [
                                    "s3:GetReplicationConfiguration",
                                    "s3:ListBucket",
                                    "s3:GetObjectVersionForReplication",
                                    "s3:GetObjectVersionAclForReplication",
                                    "s3:ReplicateObject",
                                    "s3:ReplicateDelete",
                                ],
                                Resource: [src, `${src}/*`, dst, `${dst}/*`],
                            }],
                        })),
                }],
            }, { parent: this });
            this.replicationRoleArn = replRole.arn;

            new aws.s3.BucketReplicationConfigV2(`${name}-assets-replication`, {
                bucket: bucket.id,
                role: replRole.arn,
                rules: [{
                    status: "Enabled",
                    destination: { bucket: replBucket.arn },
                }],
            }, { parent: this });
        }

        // --- RDS PostgreSQL ---
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: pulumi.output(aws.getSubnetsOutput({ filters: [{ name: "default-for-az", values: ["true"] }] }))
                .apply(s => s.ids).apply(ids => ids.slice(0, 2)),
        }, { parent: this });

        const db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: env.dbInstanceClass,
            allocatedStorage: env.dbAllocatedStorage,
            dbName: "webapp",
            username: "webapp_admin",
            password: args.dbPassword,
            dbSubnetGroupName: dbSubnetGroup.name,
            publiclyAccessible: false,
            multiAz: env.dbMultiAz,
            storageEncrypted: isProd,
            deletionProtection: true,          // both envs per acceptance criteria
            backupRetentionPeriod: 7,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-db-final`,
        }, { parent: this });
        this.db = db;

        // DB connection string as secret output (consumed by app)
        const connectionString = pulumi.secret(pulumi.interpolate
            `postgresql://webapp_admin:${args.dbPassword}@${db.endpoint}/webapp`);
        this.export("dbConnectionString", connectionString);
        this.export("bucketName", bucket.id);
        this.export("dbEndpoint", db.endpoint);

        // --- IAM role for service accounts (least privilege) ---
        const serviceRole = new aws.iam.Role(`${name}-service-role`, {
            assumeRolePolicy: isProd
                // Prod: OIDC trust for EKS service accounts (replace host with cluster OIDC issuer)
                ? JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE" },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE:sub":
                                    "system:serviceaccount:webapp:webapp",
                            },
                        },
                    }],
                })
                // Dev: programmatic/EC2 trust
                : aws.iam.assumeRolePolicyForPrincipal({ Service: "ec2.amazonaws.com" }),
            inlinePolicies: [{
                name: "app-bucket-access",
                policy: pulumi.output(bucket.arn).apply(arn => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                            Resource: `${arn}/*`,
                        },
                        {
                            Effect: "Allow",
                            Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                            Resource: arn,
                        },
                    ],
                })),
            }],
        }, { parent: this });
        this.serviceRole = serviceRole;
    }
}
